// Meta calls this once when you subscribe the webhook.
const VERIFY_TOKEN = 'change-me-to-a-long-random-string';
const q = $input.first().json.query || {};
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === VERIFY_TOKEN) {
  return [{ json: { challenge: q['hub.challenge'] } }];
}
return [{ json: { challenge: 'forbidden' } }];

// ---- EDIT THIS BLOCK -------------------------------------------------
// One entry per keyword you ask for in a Reel. Write the DM with /ig-dm so
// it sounds like you, then paste it here. Keep it plain: one link, no hype.
const MY_IG_USER_ID = 'your-instagram-user-id';   // so your own replies are ignored
const KEYWORDS = {
  AUDIT: {
    dm: "Here's the GEO checklist from the reel: https://example.com/geo-checklist\n\n" +
        "It's the same list we work through at Wellows before touching anything AI-specific. " +
        "If something in it doesn't match what you're seeing in your own data, reply here. I want to hear about it.",
    reply: "Sent it to your DMs.",
  },
};
// ---------------------------------------------------------------------

const out = [];
const body = $input.first().json.body || {};
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    if (change.field !== 'comments') continue;
    const v = change.value || {};
    if (!v.id || !v.text) continue;
    if (v.from && v.from.id === MY_IG_USER_ID) continue;
    const word = v.text.trim().replace(/[^\p{L}\p{N}]/gu, ' ').split(/\s+/)[0].toUpperCase();
    const match = KEYWORDS[word];
    if (!match) continue;
    out.push({ json: {
      comment_id: v.id,
      username: (v.from && v.from.username) || '',
      keyword: word,
      dm: match.dm,
      reply: match.reply,
    }});
  }
}
return out;
